"""100 distinct, bilingual business decisions, with executable read-only evidence queries."""
import json, re, time
from build import sqlite_db, jwrite, ZH
from explanations import explain

PATHS={
 'S01':['security_id_to_instrument','instrument_to_issuer','entity_id_to_entity','portfolio_to_manager','account_to_portfolio'],
 'S02':['order_to_account','order_to_instrument','order_to_counterparty','trade_to_order'],
 'S03':['settle_instr_to_trade','settle_event_to_settle_instr','trade_to_order'],
 'S04':['position_to_opening','opening_to_account','opening_to_instrument','trade_to_order','settle_event_to_settle_instr','settle_instr_to_trade'],
 'S05':['valuation_to_price','price_to_instrument','valuation_to_position'],
 'S06':['valuation_to_fx','valuation_to_position','position_to_opening','opening_to_instrument'],
 'S07':['valuation_to_position','valuation_to_price','valuation_to_fx','position_to_opening','opening_to_instrument'],
 'S08':['contribution_to_issuer_exp','contribution_to_valuation','issuer_exp_to_portfolio','issuer_exp_to_issuer','assessment_to_limit','assessment_to_issuer_exposure'],
 'S09':['cp_exp_to_portfolio','cp_exp_to_counterparty','assessment_to_counterparty_exposure','settle_instr_to_trade','settle_event_to_settle_instr','trade_to_order','order_to_counterparty'],
 'S10':['assessment_to_limit','limit_to_portfolio','limit_to_entity','assessment_to_issuer_exposure'],
}
TITLES=[('Reference identity','主数据身份'),('Order and executed trade','订单与成交'),('Settlement investigation','结算调查'),('Position reconciliation','持仓勾稽'),('Price quality','价格质量'),('Currency conversion','币种转换'),('Valuation and P&L','估值与损益'),('Issuer concentration','发行方集中度'),('Unsettled receivables','未结算应收'),('Dates and future mandates','日期与未来授权')]
# All SQL is local evidence verification. It is not registered as a platform function.
def build_questions(sample,data,zh):
 questions=[];answers={};db=sqlite_db(data);counts={}
 def add(s,en,cn,sql):
  counts[s]=counts.get(s,0)+1;n=counts[s];qid=f'FIN-{len(questions)+1:03}'
  level='easy_basic' if n<=3 else 'intermediate' if n<=7 else 'hard_complex'
  if zh:
   for a,b in ZH.items():sql=sql.replace("'"+a+"'","'"+b+"'")
  original_sql=sql
  views=[]
  if 'settlement_events' in sql and not re.search(r'(?:WHERE|AND) (?:e\.)?event_id=',sql):
   view='settlement_month_end' if qid=='FIN-020' else 'settlement_state'
   sql=sql.replace('settlement_events',view);views=[view]
  started=time.monotonic()
  db.set_progress_handler(lambda: int(time.monotonic()-started>30),100000)
  try:rows=[dict(r) for r in db.execute(sql)]
  except Exception as exc:raise RuntimeError(qid+' generation query failed: '+str(exc)) from exc
  finally:db.set_progress_handler(None,0)
  if len(questions)%25==24:print(sample.name,qid,'built',flush=True)
  assert rows, (qid,sql)
  evidence_tables=sorted(set(re.findall(r'\b(?:FROM|JOIN)\s+([a-z_]+)',original_sql,re.I)))
  rels=json.loads((sample/'model-contract.json').read_text())['relations']
  used_relations=[r['id'] for r in rels if r['source'] in evidence_tables and r['target'] in evidence_tables]
  questions.append(dict(id=qid,scenario_id=s,level=level,question=cn if zh else en,as_of_date='2027-02-28',evidence_tables=evidence_tables,required_relations=used_relations,evidence_views=views,evidence_sql=sql,answer_format='ordered_rows',numeric_tolerance=0.000001))
  answers[qid]={'rows':rows,'explanation':explain(qid,s,rows,zh),'evidence_rule':('按 evidence_sql 指定的记录、连接、日期和口径返回所有行；空值表示无法得出金额，禁止补零。' if zh else 'Return all rows from the specified records, joins, dates and measure. Null amounts are unknown and must not be replaced by zero.')}
 # S01
 s='S01'
 add(s,'Who issues INS-001, and what is the issuer name?','INS-001 的发行方编号和名称是什么？',"SELECT i.instrument_id,i.name,i.issuer_id,e.name AS issuer_name FROM financial_instruments i JOIN legal_entities e ON i.issuer_id=e.entity_id WHERE i.instrument_id='INS-001'")
 add(s,'What asset class and price basis does INS-002 use?','INS-002 使用什么资产类别与报价口径？',"SELECT instrument_id,asset_class,price_basis,price_multiplier,currency FROM financial_instruments WHERE instrument_id='INS-002'")
 add(s,'What is PF-049’s name and base currency?','PF-049 的名称和本位币是什么？',"SELECT portfolio_id,name,base_currency FROM portfolios WHERE portfolio_id='PF-049'")
 add(s,'Trace INS-015 through its complete security identity to its issuer: return instrument_id, synthetic_code, scheme, instrument_name, issuer_id and issuer_name.','追溯 INS-015 经合成证券编码到发行方的完整身份链，返回工具编号、合成编码、标识体系、工具名称、发行方编号和发行方名称。',"SELECT i.instrument_id,s.synthetic_code,s.scheme,i.name AS instrument_name,i.issuer_id,e.name AS issuer_name FROM security_identifiers s JOIN financial_instruments i USING(instrument_id) JOIN legal_entities e ON e.entity_id=i.issuer_id WHERE i.instrument_id='INS-015'")
 add(s,'What synthetic identifier belongs to issuer ISS-023?','发行方 ISS-023 对应哪个合成实体标识？',"SELECT e.entity_id,e.name,x.synthetic_code,x.scheme,x.is_synthetic FROM legal_entities e JOIN legal_entity_identifiers x USING(entity_id) WHERE e.entity_id='ISS-023'")
 add(s,'Which account_id, portfolio_id, manager_id and manager_name (legal_entities.name of the portfolio manager) are associated with PF-010?','PF-010 关联的账户编号、组合编号、管理人编号及管理人名称（管理人法律实体的名称）分别是什么？',"SELECT a.account_id,p.portfolio_id,p.manager_id,e.name AS manager_name FROM accounts a JOIN portfolios p USING(portfolio_id) JOIN legal_entities e ON p.manager_id=e.entity_id WHERE p.portfolio_id='PF-010'")
 add(s,'Which two instruments share issuer ISS-008, and how do their pricing units differ?','ISS-008 发行的两种工具是什么，价格单位有何不同？',"SELECT instrument_id,name,asset_class,unit,price_basis,price_multiplier FROM financial_instruments WHERE issuer_id='ISS-008' ORDER BY instrument_id")
 add(s,'Which portfolios share issuer ISS-008 at the current snapshot, and through which instruments?','当前快照中哪些组合共同暴露于 ISS-008，经由哪些工具？',"SELECT DISTINCT a.portfolio_id,i.instrument_id,i.asset_class FROM positions p JOIN opening_positions o USING(opening_id) JOIN accounts a USING(account_id) JOIN financial_instruments i USING(instrument_id) WHERE p.as_of_date='2027-02-28' AND i.issuer_id='ISS-008' ORDER BY a.portfolio_id,i.instrument_id")
 add(s,'Does each instrument resolve to one security code, an issuer-role entity, and one synthetic entity identifier? Audit the complete identity path.','每个工具是否唯一关联证券编码、发行方角色实体和合成实体标识？审计完整身份链。',"SELECT COUNT(*) AS instruments_checked,SUM(CASE WHEN security_codes<>1 OR entity_codes<>1 OR issuer_role IS NULL OR issuer_role<>'issuer' THEN 1 ELSE 0 END) AS identity_exceptions FROM (SELECT i.instrument_id,COUNT(DISTINCT s.identifier_id) AS security_codes,COUNT(DISTINCT x.identifier_id) AS entity_codes,e.entity_role AS issuer_role FROM financial_instruments i LEFT JOIN security_identifiers s USING(instrument_id) LEFT JOIN legal_entities e ON e.entity_id=i.issuer_id LEFT JOIN legal_entity_identifiers x ON x.entity_id=e.entity_id GROUP BY i.instrument_id)")
 add(s,'Audit the current position-to-portfolio-to-manager and position-to-instrument-to-issuer paths; report distinct roles and any incorrect role assignments.','审计当前持仓经组合到管理人、经工具到发行方的路径，统计不同角色实体和错误角色分配。',"SELECT COUNT(DISTINCT p.position_id) AS positions,COUNT(DISTINCT issuer.entity_id) AS issuers,COUNT(DISTINCT manager.entity_id) AS managers,SUM(CASE WHEN issuer.entity_role<>'issuer' OR manager.entity_role<>'manager' THEN 1 ELSE 0 END) AS role_errors FROM positions p JOIN opening_positions op USING(opening_id) JOIN accounts a USING(account_id) JOIN portfolios f USING(portfolio_id) JOIN legal_entities manager ON manager.entity_id=f.manager_id JOIN financial_instruments i USING(instrument_id) JOIN legal_entities issuer ON issuer.entity_id=i.issuer_id WHERE p.as_of_date='2027-02-28'")
 # S02
 s='S02'
 add(s,'What side, quantity and currency were executed in TR-001-1-4?','TR-001-1-4 的成交方向、数量与币种是什么？',"SELECT t.trade_id,o.side,t.trade_quantity,t.currency FROM securities_transactions t JOIN trade_orders o USING(order_id) WHERE t.trade_id='TR-001-1-4'")
 add(s,'What is the execution price and gross amount of TR-001-2-4?','TR-001-2-4 的成交价和成交总额是多少？',"SELECT trade_id,execution_price,gross_amount,currency FROM securities_transactions WHERE trade_id='TR-001-2-4'")
 add(s,'Which order created TR-019-2-4?','TR-019-2-4 来自哪个订单？',"SELECT trade_id,order_id,trade_date FROM securities_transactions WHERE trade_id='TR-019-2-4'")
 add(s,'Trace TR-030-4-4 to account, portfolio and counterparty.','将 TR-030-4-4 追溯到账户、组合和交易对手。',"SELECT t.trade_id,a.portfolio_id,a.account_id,o.counterparty_id FROM securities_transactions t JOIN trade_orders o USING(order_id) JOIN accounts a USING(account_id) WHERE t.trade_id='TR-030-4-4'")
 add(s,'List all actual trades executed for PF-041 in February 2027, with instrument, side, quantity, amount and currency.','列出 PF-041 在 2027 年二月的全部实际成交，包含工具、方向、数量、金额和币种。',"SELECT t.trade_id,o.instrument_id,o.side,t.trade_quantity,t.gross_amount,t.currency FROM securities_transactions t JOIN trade_orders o USING(order_id) JOIN accounts a USING(account_id) WHERE a.portfolio_id='PF-041' AND t.trade_date BETWEEN '2027-02-01' AND '2027-02-28' AND t.trade_status='executed' ORDER BY t.trade_id")
 add(s,'Explain the bond quote conversion for TR-010-2-4.','解释 TR-010-2-4 的债券报价转换。',"SELECT t.trade_id,t.trade_quantity,t.execution_price,i.price_multiplier,DROUND(DMUL(t.trade_quantity,t.execution_price,i.price_multiplier),2) AS reconstructed_gross,t.gross_amount FROM securities_transactions t JOIN trade_orders o USING(order_id) JOIN financial_instruments i USING(instrument_id) WHERE t.trade_id='TR-010-2-4'")
 add(s,'Are March trades for PF-049 actual or planned, and when were they known?','PF-049 的三月交易是实际还是计划，何时已知？',"SELECT t.trade_id,t.trade_date,t.trade_status,t.known_date FROM securities_transactions t JOIN trade_orders o USING(order_id) JOIN accounts a USING(account_id) WHERE a.portfolio_id='PF-049' AND t.trade_date>'2027-02-28' ORDER BY t.trade_id")
 add(s,'Reconcile order and executed quantities for all actual trades.','核对全部实际交易的订单与成交数量。',"SELECT COUNT(*) AS actual_trades,SUM(CASE WHEN o.order_quantity<>t.trade_quantity THEN 1 ELSE 0 END) AS quantity_mismatches FROM securities_transactions t JOIN trade_orders o USING(order_id) WHERE t.trade_status='executed'")
 add(s,'For actual buys and sells, select the latest actual USD fixing with as_of_date, published_date and known_date no later than each trade date. Group by currency and side; report trade count, the sum of booked gross_amount (local currency, already rounded per trade to 2dp), and USD total. Translate that booked gross_amount at the eligible rate, then round only the grouped USD sum; do not replace booked amounts with unrounded quantity-price products.','对实际买卖成交，选取 as_of_date、published_date、known_date 均不晚于成交日的最近实际美元汇率。按币种和买卖方向列出笔数、已入账 gross_amount 的本币合计（每笔已舍入两位）和美元合计。用已入账 gross_amount 乘适用汇率，最后对美元分组合计舍入两位；不得以未舍入的数量报价乘积替代入账金额。',"SELECT t.currency,o.side,COUNT(*) AS trades,COUNT(DISTINCT f.fx_id) AS fixing_records,ROUND(SUM(t.gross_amount),2) AS local_gross,DROUND(DSUM_PRODUCT(t.gross_amount,f.rate),2) AS usd_gross,MAX(CAST(julianday(t.trade_date)-julianday(f.published_date) AS INTEGER)) AS maximum_fixing_age FROM securities_transactions t JOIN trade_orders o USING(order_id) JOIN fx_rates f ON f.from_currency=t.currency AND f.as_of_date=(SELECT MAX(x.as_of_date) FROM fx_rates x WHERE x.from_currency=t.currency AND x.as_of_date<=t.trade_date AND x.published_date<=t.trade_date AND x.known_date<=t.trade_date AND x.view_kind='actual') WHERE t.trade_status='executed' GROUP BY t.currency,o.side ORDER BY t.currency,o.side")
 add(s,'For each trade-month cohort, currency and actual/planned view, reconcile trade count, signed booked contractual amount (sell +gross_amount, buy -gross_amount) and the remaining sell notional in that same local currency. For the latter accumulate eligible settlement transfers to that month end, then sum open sell quantity times execution quote times multiplier, rounding the local group total to 2dp. Do not translate this report to USD or carry other trade-month cohorts into a group.','按成交月份队列、币种和实际/计划视图，核对成交笔数、有符号入账合约金额（卖出 +gross_amount，买入 -gross_amount）及同一本币的剩余卖出名义金额。后者按该队列当月末累计有效结算转移量，再加总未结算卖出数量×成交报价×乘数，最后将本币分组合计舍入两位。本报告不折算美元，也不混入其他成交月份队列。',"SELECT SUBSTR(t.trade_date,1,7) AS month,t.trade_status,t.currency,COUNT(*) AS trades,ROUND(SUM(CASE WHEN o.side='sell' THEN t.gross_amount ELSE -t.gross_amount END),2) AS signed_contractual_amount,ROUND(SUM(CASE WHEN o.side='sell' THEN (t.trade_quantity-e.settled_quantity)*t.execution_price*i.price_multiplier ELSE 0 END),2) AS open_sell_receivable_local FROM securities_transactions t JOIN trade_orders o USING(order_id) JOIN financial_instruments i USING(instrument_id) JOIN settlement_instructions si USING(trade_id) JOIN settlement_events e USING(instruction_id) GROUP BY month,t.trade_status,t.currency ORDER BY month,t.trade_status,t.currency")
 # S03
 s='S03'
 add(s,'What is the settlement due date for TR-019-2-4?','TR-019-2-4 的约定结算日是什么？',"SELECT trade_id,instruction_id,due_date,required_quantity FROM settlement_instructions WHERE trade_id='TR-019-2-4'")
 add(s,'What is the failure reason of SE-030-2-4?','SE-030-2-4 的失败原因是什么？',"SELECT event_id,event_date,event_status,failure_reason,settled_quantity FROM settlement_events WHERE event_id='SE-030-2-4'")
 add(s,'What amount of quantity was settled in SE-020-2-4?','SE-020-2-4 已结算多少数量？',"SELECT event_id,event_status,settled_quantity FROM settlement_events WHERE event_id='SE-020-2-4'")
 add(s,'Is SI-019-2-4 overdue on 2027-02-28? Explain using due date and state.','截至 2027-02-28，SI-019-2-4 是否逾期？用约定日和状态解释。',"SELECT s.instruction_id,s.due_date,e.event_status,CASE WHEN s.due_date<'2027-02-28' AND e.settled_quantity<s.required_quantity THEN 1 ELSE 0 END AS overdue FROM settlement_instructions s JOIN settlement_events e USING(instruction_id) WHERE s.instruction_id='SI-019-2-4'")
 add(s,'How much remains unsettled on partial instruction SI-020-2-4?','部分结算指令 SI-020-2-4 还差多少数量？',"SELECT s.instruction_id,s.required_quantity,e.settled_quantity,s.required_quantity-e.settled_quantity AS remaining_quantity,s.due_date FROM settlement_instructions s JOIN settlement_events e USING(instruction_id) WHERE s.instruction_id='SI-020-2-4'")
 add(s,'Which broker and instrument are implicated by SE-029-4-4?','SE-029-4-4 涉及哪个经纪商和工具？',"SELECT e.event_id,e.failure_reason,o.counterparty_id,broker.name AS counterparty_name,o.instrument_id,t.trade_id FROM settlement_events e JOIN settlement_instructions s USING(instruction_id) JOIN securities_transactions t USING(trade_id) JOIN trade_orders o USING(order_id) JOIN legal_entities broker ON broker.entity_id=o.counterparty_id WHERE e.event_id='SE-029-4-4'")
 add(s,'For February 2027 actual trades of PF-001, PF-019, PF-020 and PF-029, compare settled, pending, partial and failed instruction counts and remaining quantities as of 2027-02-28. Accumulate actual event transfers known by that date.','仅对 PF-001、PF-019、PF-020、PF-029 在 2027 年二月的实际成交，按 2027-02-28 已知的实际结算事件累计转移量，比较已结算、待结算、部分结算和失败指令数及剩余数量。',"SELECT a.portfolio_id,e.event_status,COUNT(*) AS instructions,SUM(s.required_quantity-e.settled_quantity) AS remaining_quantity FROM settlement_events e JOIN settlement_instructions s USING(instruction_id) JOIN securities_transactions t USING(trade_id) JOIN trade_orders o USING(order_id) JOIN accounts a USING(account_id) WHERE a.portfolio_id IN ('PF-001','PF-019','PF-020','PF-029') AND t.trade_date BETWEEN '2027-02-01' AND '2027-02-28' GROUP BY a.portfolio_id,e.event_status ORDER BY a.portfolio_id,e.event_status")
 add(s,'Count February overdue unsettled instructions separately from unsettled instructions not yet due. Return due_state using the complete computed classification: overdue (due_date before 2027-02-28), not_due (otherwise), for instructions with cumulative settled_quantity below required_quantity.','对累计已结算量小于应结算量的二月指令分别计数。计算字段 due_state 的完整分类为：已逾期（约定结算日早于2027-02-28）、未到期（其余情况）。',"SELECT CASE WHEN s.due_date<'2027-02-28' THEN 'overdue' ELSE 'not_due' END AS due_state,COUNT(*) AS instructions FROM settlement_instructions s JOIN settlement_events e USING(instruction_id) JOIN securities_transactions t USING(trade_id) WHERE t.trade_date BETWEEN '2027-02-01' AND '2027-02-28' AND e.settled_quantity<s.required_quantity GROUP BY due_state ORDER BY due_state")
 add(s,'How many failed February instructions arise from each failure reason and side?','二月失败指令按原因和交易方向分别有多少笔？',"SELECT e.failure_reason,o.side,COUNT(*) AS instructions FROM settlement_events e JOIN settlement_instructions s USING(instruction_id) JOIN securities_transactions t USING(trade_id) JOIN trade_orders o USING(order_id) WHERE e.event_status='failed' AND t.trade_date BETWEEN '2027-02-01' AND '2027-02-28' GROUP BY e.failure_reason,o.side ORDER BY e.failure_reason,o.side")
 add(s,'Reconcile required, settled and remaining quantities by instrument unit for actual trades.','按工具数量单位汇总实际交易的应结算、已结算和剩余数量并勾稽。',"SELECT i.unit,SUM(s.required_quantity) AS required_quantity,SUM(e.settled_quantity) AS settled_quantity,SUM(s.required_quantity-e.settled_quantity) AS remaining_quantity FROM settlement_instructions s JOIN settlement_events e USING(instruction_id) JOIN securities_transactions t USING(trade_id) JOIN trade_orders o USING(order_id) JOIN financial_instruments i USING(instrument_id) WHERE t.trade_status='executed' GROUP BY i.unit ORDER BY i.unit")
 # S04
 s='S04'
 add(s,'What are the two quantity bases of POS-019-2-4?','POS-019-2-4 的交易日和结算日数量分别是多少？',"SELECT position_id,trade_basis_quantity,settled_basis_quantity,unsettled_delta FROM positions WHERE position_id='POS-019-2-4'")
 add(s,'What quantity opened OP-001-1?','OP-001-1 的期初数量是多少？',"SELECT opening_id,opening_date,quantity,cost_unit_price FROM opening_positions WHERE opening_id='OP-001-1'")
 add(s,'Which date and view does POS-050-4-5 represent?','POS-050-4-5 对应什么日期和视图？',"SELECT position_id,as_of_date,view_kind,known_date FROM positions WHERE position_id='POS-050-4-5'")
 add(s,'Trace POS-030-4-4 to instrument and portfolio.','将 POS-030-4-4 追溯到工具和组合。',"SELECT p.position_id,a.portfolio_id,o.instrument_id FROM positions p JOIN opening_positions o USING(opening_id) JOIN accounts a USING(account_id) WHERE p.position_id='POS-030-4-4'")
 add(s,'Do the quantity bases reconcile for PF-020 at the current date?','当前日期 PF-020 的两种数量口径能否勾稽？',"SELECT p.position_id,p.trade_basis_quantity,p.settled_basis_quantity,p.unsettled_delta,ROUND(p.trade_basis_quantity-p.settled_basis_quantity-p.unsettled_delta,6) AS reconciliation_error FROM positions p JOIN opening_positions o USING(opening_id) JOIN accounts a USING(account_id) WHERE a.portfolio_id='PF-020' AND p.as_of_date='2027-02-28' ORDER BY p.position_id")
 add(s,'Compare the current sell-side unsettled deltas of positions POS-001-2-4 and POS-029-2-4; explain the sign and distinguish these positions from portfolio totals.','比较持仓 POS-001-2-4 与 POS-029-2-4 当前卖出未结算差量，解释正负号，并区分所选持仓与组合合计。',"SELECT a.portfolio_id,p.position_id,p.unsettled_delta FROM positions p JOIN opening_positions o USING(opening_id) JOIN accounts a USING(account_id) WHERE a.portfolio_id IN ('PF-001','PF-029') AND p.as_of_date='2027-02-28' AND p.position_id LIKE '%-2-4' ORDER BY a.portfolio_id")
 add(s,'Show the five snapshots of opening position OP-049-1 and their view kinds.','展示期初持仓 OP-049-1 的五个快照及视图类型。',"SELECT position_id,as_of_date,view_kind,trade_basis_quantity,settled_basis_quantity FROM positions WHERE opening_id='OP-049-1' ORDER BY as_of_date")
 add(s,'Reconstruct POS-020-2-4 trade-date quantity from opening plus signed actual trades.','用期初数量与实际买卖成交重建 POS-020-2-4 的交易日数量。',"SELECT p.position_id,p.trade_basis_quantity,o.quantity+SUM(CASE WHEN z.side='buy' THEN t.trade_quantity ELSE -t.trade_quantity END) AS reconstructed FROM positions p JOIN opening_positions o USING(opening_id) JOIN trade_orders z ON z.account_id=o.account_id AND z.instrument_id=o.instrument_id JOIN securities_transactions t ON t.order_id=z.order_id WHERE p.position_id='POS-020-2-4' AND t.trade_date<=p.as_of_date AND t.trade_status='executed' GROUP BY p.position_id")
 add(s,'Reconstruct POS-029-4-4 settled quantity from opening and settlement events.','用期初和结算事件重建 POS-029-4-4 的结算日数量。',"SELECT p.position_id,p.settled_basis_quantity,o.quantity+SUM(CASE WHEN z.side='buy' THEN e.settled_quantity ELSE -e.settled_quantity END) AS reconstructed FROM positions p JOIN opening_positions o USING(opening_id) JOIN trade_orders z ON z.account_id=o.account_id AND z.instrument_id=o.instrument_id JOIN securities_transactions t USING(order_id) JOIN settlement_instructions s USING(trade_id) JOIN settlement_events e USING(instruction_id) WHERE p.position_id='POS-029-4-4' AND e.event_date<=p.as_of_date AND t.trade_status='executed' GROUP BY p.position_id")
 add(s,'Across the full actual position-snapshot history from November 2026 through February 2027, count dated position records, quantity reconciliation failures and records with nonzero unsettled delta. Include all historical actual snapshots, not only the current snapshot; exclude March plans.','在 2026 年十一月至 2027 年二月的全部实际持仓快照历史中，统计有日期的持仓记录数、数量勾稽失败数和未结算差量非零记录数。包含各期历史实际快照，不仅限于当前快照，排除三月计划。',"SELECT COUNT(*) AS actual_positions,SUM(CASE WHEN ABS(trade_basis_quantity-settled_basis_quantity-unsettled_delta)>0.000001 THEN 1 ELSE 0 END) AS reconciliation_failures,SUM(CASE WHEN unsettled_delta<>0 THEN 1 ELSE 0 END) AS open_unsettled_positions FROM positions WHERE view_kind='actual'")
 # S05
 s='S05'
 add(s,'What is PX-001-4’s date, source and approval?','PX-001-4 的日期、来源及批准状态是什么？',"SELECT price_id,price_date,pricing_source,approval FROM market_prices WHERE price_id='PX-001-4'")
 add(s,'Why is VAL-035-1-4 blocked?','VAL-035-1-4 为什么受阻？',"SELECT valuation_id,valuation_status,reason,price_id,market_value_base FROM valuation_snapshots WHERE valuation_id='VAL-035-1-4'")
 add(s,'Is the February price for INS-073 present?','INS-073 的二月价格是否存在？',"SELECT i.instrument_id,COUNT(p.price_id) AS price_count FROM financial_instruments i LEFT JOIN market_prices p ON p.instrument_id=i.instrument_id AND p.price_id='PX-073-4' WHERE i.instrument_id='INS-073' GROUP BY i.instrument_id")
 add(s,'How old is the price used by VAL-035-1-4? Return valuation_id, as_of_date, price_date, age_days and valuation_reason, copying valuation_snapshots.reason exactly as stored rather than writing a free-form explanation.','VAL-035-1-4 所关联价格距估值日多少天？返回估值编号、截至日期、价格日期、日龄及 valuation_reason（估值原因）；估值原因须原样返回 valuation_snapshots.reason 的存储值，不作自由解释。',"SELECT v.valuation_id,v.as_of_date,p.price_date,CAST(julianday(v.as_of_date)-julianday(p.price_date) AS INTEGER) AS age_days,v.reason AS valuation_reason FROM valuation_snapshots v JOIN market_prices p USING(price_id) WHERE v.valuation_id='VAL-035-1-4'")
 add(s,'Which approval explains the exception of VAL-036-1-4?','VAL-036-1-4 的例外由哪项价格批准状态解释？',"SELECT v.valuation_id,v.reason,p.price_id,p.approval FROM valuation_snapshots v JOIN market_prices p USING(price_id) WHERE v.valuation_id='VAL-036-1-4'")
 add(s,'Does missing price VAL-037-1-4 fabricate a zero market value?','价格缺失的 VAL-037-1-4 是否把市值伪造为零？',"SELECT valuation_id,price_id,market_value_base,valuation_status,reason FROM valuation_snapshots WHERE valuation_id='VAL-037-1-4'")
 add(s,'Which portfolios share the defective February price for INS-069?','哪些组合共同受到 INS-069 二月缺陷价格影响？',"SELECT a.portfolio_id,v.valuation_id,v.reason FROM valuation_snapshots v JOIN positions p USING(position_id) JOIN opening_positions o USING(opening_id) JOIN accounts a USING(account_id) WHERE o.instrument_id='INS-069' AND v.as_of_date='2027-02-28' ORDER BY a.portfolio_id")
 add(s,'Count all February valuation exceptions by reason and affected portfolios.','按原因统计二月全部估值例外数量和受影响组合数。',"SELECT v.reason,COUNT(*) AS valuations,COUNT(DISTINCT a.portfolio_id) AS portfolios FROM valuation_snapshots v JOIN positions p USING(position_id) JOIN opening_positions o USING(opening_id) JOIN accounts a USING(account_id) WHERE v.as_of_date='2027-02-28' AND v.valuation_status='blocked' GROUP BY v.reason ORDER BY v.reason")
 add(s,'Which February issuer assessments must remain unknown because portfolio prices are incomplete?','哪些二月发行方评估因组合价格不完整而必须保持无法判定？',"SELECT l.portfolio_id,a.assessment_id,a.assessment_status,a.observed_value FROM limit_assessments a JOIN mandate_limits l USING(limit_id) WHERE a.as_of_date='2027-02-28' AND a.assessment_status='unknown' ORDER BY l.portfolio_id,a.assessment_id")
 add(s,'Did all February price-blocked valuations also have failed settlements? Test the proposition with state evidence.','二月价格受阻估值是否都伴随结算失败？用结算状态检验。',"SELECT v.reason,e.event_status,COUNT(*) AS valuations FROM valuation_snapshots v JOIN positions p USING(position_id) JOIN opening_positions o USING(opening_id) JOIN trade_orders z ON z.account_id=o.account_id AND z.instrument_id=o.instrument_id JOIN securities_transactions t USING(order_id) JOIN settlement_instructions s USING(trade_id) JOIN settlement_events e USING(instruction_id) WHERE v.as_of_date='2027-02-28' AND v.valuation_status='blocked' AND t.trade_date BETWEEN '2027-02-01' AND '2027-02-28' GROUP BY v.reason,e.event_status ORDER BY v.reason,e.event_status")
 # S06
 s='S06'
 add(s,'What USD conversion rate is FX-CNY-2027-02-28?','FX-CNY-2027-02-28 的美元转换汇率是多少？',"SELECT fx_id,from_currency,to_currency,rate,as_of_date FROM fx_rates WHERE fx_id='FX-CNY-2027-02-28'")
 add(s,'What source and target currencies does FX-EUR-2027-01-31 use?','FX-EUR-2027-01-31 使用什么源币种和目标币种？',"SELECT fx_id,from_currency,to_currency,rate FROM fx_rates WHERE fx_id='FX-EUR-2027-01-31'")
 add(s,'What is the self-currency USD conversion rate on 2027-02-28?','2027-02-28 美元兑自身的转换汇率是多少？',"SELECT fx_id,rate FROM fx_rates WHERE fx_id='FX-USD-2027-02-28'")
 add(s,'Trace VAL-001-1-4 to its exact dated FX record.','将 VAL-001-1-4 追溯到准确的带日期汇率记录。',"SELECT v.valuation_id,f.fx_id,f.as_of_date,f.rate,f.from_currency,f.to_currency FROM valuation_snapshots v JOIN fx_rates f USING(fx_id) WHERE v.valuation_id='VAL-001-1-4'")
 add(s,'Reconstruct USD value for VAL-003-1-4 using EUR market value and rate.','用欧元市值和汇率重建 VAL-003-1-4 的美元市值。',"SELECT v.valuation_id,v.market_value_local,f.rate,DROUND(DMUL(v.market_value_local,f.rate),2) AS reconstructed_base,v.market_value_base FROM valuation_snapshots v JOIN fx_rates f USING(fx_id) WHERE v.valuation_id='VAL-003-1-4'")
 add(s,'Do the FX dates and valuation dates match for all February valuations?','全部二月估值的汇率日期与估值日期是否一致？',"SELECT COUNT(*) AS valuations,SUM(CASE WHEN v.as_of_date<>f.as_of_date THEN 1 ELSE 0 END) AS date_mismatches FROM valuation_snapshots v JOIN fx_rates f USING(fx_id) WHERE v.as_of_date='2027-02-28'")
 add(s,'Which local currencies feed USD valuations for PF-001 and PF-003?','PF-001 和 PF-003 的美元估值由哪些交易币种转换而来？',"SELECT DISTINCT a.portfolio_id,f.from_currency,f.to_currency,f.rate FROM valuation_snapshots v JOIN fx_rates f USING(fx_id) JOIN positions p USING(position_id) JOIN opening_positions o USING(opening_id) JOIN accounts a USING(account_id) WHERE a.portfolio_id IN ('PF-001','PF-003') AND v.as_of_date='2027-02-28' ORDER BY a.portfolio_id,f.from_currency")
 add(s,'Aggregate complete February values by source currency with separate local and USD totals.','按源币种汇总二月完整估值，分别列交易币种总额和美元总额。',"SELECT f.from_currency,COUNT(*) AS valuations,ROUND(SUM(v.market_value_local),2) AS local_total,ROUND(SUM(v.market_value_base),2) AS usd_total FROM valuation_snapshots v JOIN fx_rates f USING(fx_id) WHERE v.as_of_date='2027-02-28' AND v.valuation_status='complete' GROUP BY f.from_currency ORDER BY f.from_currency")
 add(s,'Compare PF-003 January and February USD values and FX rates without calling the difference trading profit.','比较 PF-003 一月和二月美元市值与汇率，不将差额直接当作交易利润。',"SELECT v.as_of_date,f.from_currency,f.rate,ROUND(SUM(v.market_value_base),2) AS usd_value FROM valuation_snapshots v JOIN fx_rates f USING(fx_id) JOIN positions p USING(position_id) JOIN opening_positions o USING(opening_id) JOIN accounts a USING(account_id) WHERE a.portfolio_id='PF-003' AND v.as_of_date IN ('2027-01-31','2027-02-28') GROUP BY v.as_of_date,f.from_currency,f.rate ORDER BY v.as_of_date,f.from_currency")
 add(s,'Across the full complete actual valuation-snapshot history from November 2026 through February 2027, count valuations and audit whether FX source currency matches each instrument and target currency is USD. Include every actual valuation date, not only the current snapshot.','对 2026 年十一月至 2027 年二月全部完整实际估值快照历史，统计估值记录数，并审计汇率源币是否匹配工具币种、目标币是否为 USD。包含所有实际估值日期，不仅限于当前快照。',"SELECT COUNT(*) AS valuations,SUM(CASE WHEN i.currency<>f.from_currency OR f.to_currency<>'USD' THEN 1 ELSE 0 END) AS currency_mismatches FROM valuation_snapshots v JOIN fx_rates f USING(fx_id) JOIN positions p USING(position_id) JOIN opening_positions o USING(opening_id) JOIN financial_instruments i USING(instrument_id) WHERE v.view_kind='actual' AND v.valuation_status='complete'")
 # S07
 s='S07'
 add(s,'What method is used by VAL-001-2-4?','VAL-001-2-4 使用什么估值方法？',"SELECT valuation_id,valuation_method,valuation_status FROM valuation_snapshots WHERE valuation_id='VAL-001-2-4'")
 add(s,'What USD market value and cost belong to VAL-002-1-4?','VAL-002-1-4 的美元市值和成本是多少？',"SELECT valuation_id,market_value_base,cost_value_base,currency FROM valuation_snapshots WHERE valuation_id='VAL-002-1-4'")
 add(s,'What unrealized USD P&L belongs to VAL-004-2-4?','VAL-004-2-4 的美元未实现损益是多少？',"SELECT valuation_id,unrealized_pnl_base,currency FROM valuation_snapshots WHERE valuation_id='VAL-004-2-4'")
 add(s,'Explain the complete equity valuation equation for VAL-001-1-4.','解释 VAL-001-1-4 的完整股票估值公式。',"SELECT v.valuation_id,p.trade_basis_quantity,x.price,i.price_multiplier,f.rate,v.market_value_base FROM valuation_snapshots v JOIN positions p USING(position_id) JOIN opening_positions o USING(opening_id) JOIN financial_instruments i USING(instrument_id) JOIN market_prices x USING(price_id) JOIN fx_rates f USING(fx_id) WHERE v.valuation_id='VAL-001-1-4'")
 add(s,'Explain the full-price-per-100 bond valuation equation for VAL-003-2-4.','解释 VAL-003-2-4 按每百元面值全价计算的债券估值公式。',"SELECT v.valuation_id,p.trade_basis_quantity,i.price_basis,x.price,i.price_multiplier,f.rate,v.market_value_base FROM valuation_snapshots v JOIN positions p USING(position_id) JOIN opening_positions o USING(opening_id) JOIN financial_instruments i USING(instrument_id) JOIN market_prices x USING(price_id) JOIN fx_rates f USING(fx_id) WHERE v.valuation_id='VAL-003-2-4'")
 add(s,'Reconcile unrealized P&L of PF-001 from USD market value minus translated cost.','用美元市值减折算成本核对 PF-001 的未实现损益。',"SELECT v.valuation_id,v.market_value_base,v.cost_value_base,v.unrealized_pnl_base,DROUND(DSUB(v.market_value_base,v.cost_value_base),2) AS reconstructed_pnl FROM valuation_snapshots v JOIN positions p USING(position_id) JOIN opening_positions o USING(opening_id) JOIN accounts a USING(account_id) WHERE a.portfolio_id='PF-001' AND v.as_of_date='2027-02-28' ORDER BY v.valuation_id")
 add(s,'Why is a partial sum for PF-037 not an accepted portfolio value? Show total and complete position counts.','为什么 PF-037 的部分市值加总不能作为完整组合估值？展示持仓总数和完整估值数。',"SELECT a.portfolio_id,COUNT(*) AS positions,SUM(CASE WHEN v.valuation_status='complete' THEN 1 ELSE 0 END) AS complete_valuations,ROUND(SUM(v.market_value_base),2) AS partial_usd_value FROM valuation_snapshots v JOIN positions p USING(position_id) JOIN opening_positions o USING(opening_id) JOIN accounts a USING(account_id) WHERE a.portfolio_id='PF-037' AND v.as_of_date='2027-02-28' GROUP BY a.portfolio_id")
 add(s,'By actual valuation date, reconcile fully accepted versus incomplete portfolio counts and total accepted portfolio value, excluding partial totals.','按实际估值日核对完整与不完整组合数及完整组合总市值，排除部分加总。',"SELECT as_of_date,COUNT(*) AS portfolios,SUM(CASE WHEN complete_count=8 THEN 1 ELSE 0 END) AS accepted_portfolios,SUM(CASE WHEN complete_count<8 THEN 1 ELSE 0 END) AS incomplete_portfolios,ROUND(SUM(CASE WHEN complete_count=8 THEN value ELSE 0 END),2) AS accepted_usd_value FROM (SELECT v.as_of_date,a.portfolio_id,SUM(CASE WHEN v.valuation_status='complete' THEN 1 ELSE 0 END) AS complete_count,SUM(v.market_value_base) AS value FROM valuation_snapshots v JOIN positions p USING(position_id) JOIN opening_positions op USING(opening_id) JOIN accounts a USING(account_id) WHERE v.view_kind='actual' GROUP BY v.as_of_date,a.portfolio_id) GROUP BY as_of_date ORDER BY as_of_date")
 add(s,'List each accepted February portfolio and its USD total value, accepting only portfolios whose eight positions all have complete valuation; return the complete portfolio-level list, not just a grand total.','仅接受八项持仓均估值完整的二月组合，逐组合列出编号和美元总市值；返回完整组合清单，而非仅给全部组合总计。',"SELECT a.portfolio_id,ROUND(SUM(v.market_value_base),2) AS accepted_usd_value FROM valuation_snapshots v JOIN positions p USING(position_id) JOIN opening_positions o USING(opening_id) JOIN accounts a USING(account_id) WHERE v.as_of_date='2027-02-28' GROUP BY a.portfolio_id HAVING COUNT(*)=8 AND SUM(CASE WHEN v.valuation_status='complete' THEN 1 ELSE 0 END)=8 ORDER BY a.portfolio_id")
 add(s,'Reconstruct the January sale P&L for OP-001-1 from opening cost plus November and December purchases; compare with its recorded realized P&L.','用期初成本加十一、十二月买入成本，重算 OP-001-1 一月卖出的加权平均成本损益并核对记录。',"SELECT op.opening_id,jan.position_id,op.quantity AS opening_quantity,ROUND(SUM(prior.gross_amount),2) AS prior_buy_cost,SUM(prior.trade_quantity) AS prior_buy_quantity,sale.trade_quantity AS sold_quantity,ROUND(sale.trade_quantity*(sale.execution_price-(op.quantity*op.cost_unit_price+SUM(prior.gross_amount))/(op.quantity+SUM(prior.trade_quantity))),2) AS reconstructed_realized_pnl,jan.realized_pnl FROM opening_positions op JOIN positions jan USING(opening_id) JOIN trade_orders z ON z.account_id=op.account_id AND z.instrument_id=op.instrument_id JOIN securities_transactions prior ON prior.order_id=z.order_id JOIN securities_transactions sale ON sale.trade_id='TR-001-1-3' WHERE op.opening_id='OP-001-1' AND jan.as_of_date='2027-01-31' AND z.side='buy' AND prior.trade_date<sale.trade_date GROUP BY op.opening_id")
 # S08
 s='S08'
 add(s,'What is the current concentration limit LIM-041-I1?','当前集中度限额 LIM-041-I1 是多少？',"SELECT limit_id,entity_id,measure,threshold,effective_from_date,effective_to_date FROM mandate_limits WHERE limit_id='LIM-041-I1'")
 add(s,'What is the result of LA-LIM-041-I1-4?','LA-LIM-041-I1-4 的评估结果是什么？',"SELECT assessment_id,observed_value,assessment_status,excess_value FROM limit_assessments WHERE assessment_id='LA-LIM-041-I1-4'")
 add(s,'What is the February denominator for IE-001-1-4?','IE-001-1-4 的二月分母金额是多少？',"SELECT e.exposure_id,e.exposure_amount,e.denominator_amount,e.ratio,e.currency,p.name AS portfolio_name,i.name AS issuer_name FROM issuer_exposures e JOIN portfolios p USING(portfolio_id) JOIN legal_entities i ON i.entity_id=e.issuer_id WHERE e.exposure_id='IE-001-1-4'")
 add(s,'Which valuations contribute to IE-041-1-4?','哪些估值构成 IE-041-1-4？',"SELECT c.contribution_id,c.valuation_id,c.contribution_amount FROM exposure_contributions c WHERE c.exposure_id='IE-041-1-4' ORDER BY c.valuation_id")
 add(s,'Reconcile IE-041-1-4 exposure from its two position contributions.','用两项持仓构成核对 IE-041-1-4 的敞口。',"SELECT e.exposure_id,e.exposure_amount,ROUND(SUM(c.contribution_amount),2) AS contribution_total,e.ratio,e.denominator_amount FROM issuer_exposures e JOIN exposure_contributions c USING(exposure_id) WHERE e.exposure_id='IE-041-1-4' GROUP BY e.exposure_id")
 add(s,'Trace PF-043’s current issuer breaches to issuer names and thresholds.','将 PF-043 当前发行方超限追溯到发行方名称和阈值。',"SELECT l.portfolio_id,e.name,a.assessment_id,a.observed_value,l.threshold,a.assessment_status FROM limit_assessments a JOIN mandate_limits l USING(limit_id) JOIN legal_entities e ON l.entity_id=e.entity_id WHERE l.portfolio_id='PF-043' AND a.as_of_date='2027-02-28' AND l.measure='issuer_ratio' AND a.assessment_status='breach' ORDER BY a.assessment_id")
 add(s,'Does PF-035 have a complete denominator for issuer concentration?','PF-035 的发行方集中度是否有完整分母？',"SELECT exposure_id,exposure_status,denominator_amount,ratio FROM issuer_exposures WHERE portfolio_id='PF-035' AND as_of_date='2027-02-28' ORDER BY exposure_id")
 add(s,'List all current issuer breaches with the source issuer and excess in ratio points.','列出全部当前发行方超限，并显示发行方与超限比例值。',"SELECT l.portfolio_id,l.entity_id,a.observed_value,l.threshold,a.excess_value FROM limit_assessments a JOIN mandate_limits l USING(limit_id) WHERE a.as_of_date='2027-02-28' AND l.measure='issuer_ratio' AND a.assessment_status='breach' ORDER BY l.portfolio_id,l.entity_id")
 add(s,'For every complete portfolio at 2027-02-28, report issuer count and the sum of all issuer shares; do they sum to one?','对 2027-02-28 的每个完整组合，列出发行方数量和全部发行方份额之和；是否合计为一？',"SELECT portfolio_id,ROUND(SUM(ratio),6) AS sum_ratio,COUNT(*) AS issuers FROM issuer_exposures WHERE as_of_date='2027-02-28' AND exposure_status='complete' GROUP BY portfolio_id ORDER BY portfolio_id")
 add(s,'For current PF-041 issuer breaches, trace contributing valuations to opening balances, related current-month trades and settlement outcomes; do not attribute the whole stock exposure to those trades.','针对 PF-041 当前发行方超限，追溯构成估值、期初存量、关联当月交易和结算结果，不将全部存量敞口归因于当月成交。',"SELECT a.assessment_id,e.exposure_id,e.issuer_id,c.valuation_id,p.position_id,op.instrument_id,op.quantity AS opening_quantity,p.trade_basis_quantity,t.trade_id,z.side,t.trade_quantity,si.instruction_id,si.due_date,se.event_status,se.settled_quantity,si.required_quantity-se.settled_quantity AS remaining_quantity,se.failure_reason FROM limit_assessments a JOIN issuer_exposures e ON a.issuer_exposure_id=e.exposure_id JOIN exposure_contributions c USING(exposure_id) JOIN valuation_snapshots v USING(valuation_id) JOIN positions p USING(position_id) JOIN opening_positions op USING(opening_id) JOIN trade_orders z ON z.account_id=op.account_id AND z.instrument_id=op.instrument_id JOIN securities_transactions t USING(order_id) JOIN settlement_instructions si USING(trade_id) JOIN settlement_events se USING(instruction_id) WHERE e.portfolio_id='PF-041' AND a.as_of_date='2027-02-28' AND a.assessment_status='breach' AND t.trade_date BETWEEN '2027-02-01' AND '2027-02-28' ORDER BY a.assessment_id,op.instrument_id,t.trade_id")
 # S09
 s='S09'
 add(s,'What is CE-046-4’s unsettled USD receivable?','CE-046-4 的未结算美元应收金额是多少？',"SELECT exposure_id,unsettled_receivable,currency,as_of_date FROM counterparty_exposures WHERE exposure_id='CE-046-4'")
 add(s,'What is the receivable threshold for PF-046?','PF-046 的未结算应收限额是多少？',"SELECT limit_id,threshold,currency,measure FROM mandate_limits WHERE limit_id='LIM-046-C'")
 add(s,'Which counterparty is recorded on CE-047-4?','CE-047-4 记录了哪个交易对手？',"SELECT c.exposure_id,c.counterparty_id,e.name AS counterparty_name FROM counterparty_exposures c JOIN legal_entities e ON e.entity_id=c.counterparty_id WHERE c.exposure_id='CE-047-4'")
 add(s,'Compare PF-001’s settled receivable with PF-019’s pending receivable.','比较 PF-001 已结算情形和 PF-019 待结算情形的未结算应收。',"SELECT portfolio_id,unsettled_receivable,currency FROM counterparty_exposures WHERE portfolio_id IN ('PF-001','PF-019') AND as_of_date='2027-02-28' ORDER BY portfolio_id")
 add(s,'Audit every February SELL trade for PF-046 as of 2027-02-28, including fully settled trades with open_quantity=0. Return each trade and its side, instrument currency, remaining quantity, execution price, price multiplier and stored settlement failure reason; this is the full trade audit scope.','截至2027-02-28逐笔核对 PF-046 的全部二月卖出成交，包括已全结且 open_quantity=0 的行。返回成交编号、方向、工具币种、剩余数量、成交价格、价格乘数及存储的结算失败原因；范围为全部卖出成交审计。',"SELECT t.trade_id,o.side,i.currency,t.trade_quantity-e.settled_quantity AS open_quantity,t.execution_price,i.price_multiplier,e.failure_reason FROM securities_transactions t JOIN trade_orders o USING(order_id) JOIN accounts a USING(account_id) JOIN financial_instruments i USING(instrument_id) JOIN settlement_instructions s USING(trade_id) JOIN settlement_events e USING(instruction_id) WHERE a.portfolio_id='PF-046' AND t.trade_date BETWEEN '2027-02-01' AND '2027-02-28' AND o.side='sell' ORDER BY t.trade_id")
 add(s,'What assessment and excess amount explain PF-048’s current counterparty breach?','哪项评估与超限金额解释 PF-048 当前交易对手超限？',"SELECT a.assessment_id,a.counterparty_exposure_id,a.observed_value,l.threshold,a.excess_value,a.assessment_status FROM limit_assessments a JOIN mandate_limits l USING(limit_id) WHERE l.portfolio_id='PF-048' AND l.measure='receivable_amount' AND a.as_of_date='2027-02-28'")
 add(s,'Are PF-029 and PF-046 both settlement failures but different limit outcomes?','PF-029 与 PF-046 都有结算失败，限额结论是否不同？',"SELECT l.portfolio_id,a.observed_value,l.threshold,a.assessment_status FROM limit_assessments a JOIN mandate_limits l USING(limit_id) WHERE l.portfolio_id IN ('PF-029','PF-046') AND l.measure='receivable_amount' AND a.as_of_date='2027-02-28' ORDER BY l.portfolio_id")
 add(s,'Trace PF-046’s current receivable breach to each open sell instruction, cumulative settlement state and USD contribution; reconcile the total against the assessed limit. Display each USD trade_contribution rounded to 2 decimal places; sum the unrounded quantity × execution_price × price_multiplier × FX contributions first, then round reconstructed_receivable to 2 decimal places.','将 PF-046 当前应收超限追溯到每笔未结算卖出指令、累计结算状态及美元构成，并将合计与限额评估勾稽。各笔 trade_contribution 为美元显示金额，舍入两位；先加总未舍入的剩余数量×成交价×价格乘数×汇率构成，再将 reconstructed_receivable 合计舍入两位。',"SELECT a.portfolio_id,c.counterparty_id,la.assessment_id,la.assessment_status,l.threshold,t.trade_id,s.instruction_id,s.due_date,e.event_status,e.failure_reason,t.trade_quantity,e.settled_quantity,t.trade_quantity-e.settled_quantity AS open_quantity,DROUND(DMUL(DSUB(t.trade_quantity,e.settled_quantity),t.execution_price,i.price_multiplier,f.rate),2) AS trade_contribution,ROUND(SUM((t.trade_quantity-e.settled_quantity)*t.execution_price*i.price_multiplier*f.rate) OVER (),2) AS reconstructed_receivable,c.unsettled_receivable FROM securities_transactions t JOIN trade_orders o USING(order_id) JOIN accounts a USING(account_id) JOIN financial_instruments i USING(instrument_id) JOIN settlement_instructions s USING(trade_id) JOIN settlement_events e USING(instruction_id) JOIN fx_rates f ON f.from_currency=i.currency AND f.as_of_date='2027-02-28' JOIN counterparty_exposures c ON c.portfolio_id=a.portfolio_id AND c.as_of_date='2027-02-28' JOIN limit_assessments la ON la.counterparty_exposure_id=c.exposure_id JOIN mandate_limits l USING(limit_id) WHERE a.portfolio_id='PF-046' AND t.trade_date<='2027-02-28' AND o.side='sell' AND t.trade_quantity>e.settled_quantity ORDER BY t.trade_id")
 add(s,'Which current counterparty receivable limits breach, and what is total excess USD?','当前哪些交易对手未结算应收限额超限，总超限美元金额是多少？',"SELECT l.portfolio_id,l.limit_id,a.assessment_id,a.observed_value,l.threshold,a.excess_value,COUNT(*) OVER () AS breached_limits,ROUND(SUM(a.excess_value) OVER (),2) AS excess_usd FROM limit_assessments a JOIN mandate_limits l USING(limit_id) WHERE a.as_of_date='2027-02-28' AND l.measure='receivable_amount' AND a.assessment_status='breach' ORDER BY l.portfolio_id,l.limit_id")
 add(s,'Compare all seven business branches by current receivable and breached receivable limits.','按七种业务分支比较当前未结算应收金额与未结算应收金额限额的超限数量。',"SELECT p.branch,COUNT(*) AS portfolios,ROUND(SUM(c.unsettled_receivable),2) AS usd_receivable,SUM(CASE WHEN a.assessment_status='breach' THEN 1 ELSE 0 END) AS breached_limits FROM portfolios p JOIN counterparty_exposures c USING(portfolio_id) JOIN limit_assessments a ON a.counterparty_exposure_id=c.exposure_id WHERE c.as_of_date='2027-02-28' GROUP BY p.branch ORDER BY p.branch")
 # S10
 s='S10'
 add(s,'When does the next version of PF-049 issuer limit LIM-049-I1 become effective?','PF-049 的发行方限额 LIM-049-I1 下一版本何时生效？',"SELECT limit_id,effective_from_date,threshold,decision_date FROM mandate_limits WHERE limit_id='LIM-049-I1-NEXT'")
 add(s,'What current and planning dates exist for positions?','持仓包含哪些实际日期和计划日期？',"SELECT as_of_date,view_kind,COUNT(*) AS positions FROM positions GROUP BY as_of_date,view_kind ORDER BY as_of_date")
 add(s,'Is VAL-049-1-5 a current fact or a forecast?','VAL-049-1-5 是当前事实还是计划预测？',"SELECT valuation_id,as_of_date,view_kind,known_date FROM valuation_snapshots WHERE valuation_id='VAL-049-1-5'")
 add(s,'Which issuer limits apply to PF-049 on 2027-02-28?','2027-02-28 PF-049 应适用哪些发行方限额？',"SELECT limit_id,entity_id,threshold,effective_from_date,effective_to_date FROM mandate_limits WHERE portfolio_id='PF-049' AND measure='issuer_ratio' AND effective_from_date<='2027-02-28' AND effective_to_date>='2027-02-28' AND decision_date<='2027-02-28' ORDER BY limit_id")
 add(s,'Which issuer limits apply to PF-049’s March planning snapshot?','PF-049 三月计划快照应适用哪些发行方限额？',"SELECT limit_id,entity_id,threshold,effective_from_date,effective_to_date FROM mandate_limits WHERE portfolio_id='PF-049' AND measure='issuer_ratio' AND effective_from_date<='2027-03-31' AND effective_to_date>='2027-03-31' AND decision_date<='2027-02-28' ORDER BY limit_id")
 add(s,'Compare PF-050’s February actual and March planned issuer assessments.','比较 PF-050 二月实际与三月计划的发行方评估。',"SELECT a.as_of_date,a.view_kind,l.limit_id,l.threshold,a.observed_value,a.assessment_status FROM limit_assessments a JOIN mandate_limits l USING(limit_id) WHERE l.portfolio_id='PF-050' AND l.measure='issuer_ratio' AND a.as_of_date IN ('2027-02-28','2027-03-31') ORDER BY a.as_of_date,l.limit_id")
 add(s,'Were all future mandate changes known by the February as-of date?','全部未来授权变更是否在二月截至日之前已知？',"SELECT limit_id,decision_date,effective_from_date FROM mandate_limits WHERE limit_id LIKE '%-NEXT' ORDER BY limit_id")
 add(s,'Audit whether any actual position, price, FX or trade is dated after 2027-02-28.','审计实际持仓、价格、汇率或交易中是否混入 2027-02-28 之后的数据。',"SELECT 'positions' AS source,COUNT(*) AS future_actual_rows FROM positions WHERE view_kind='actual' AND as_of_date>'2027-02-28' UNION ALL SELECT 'prices',COUNT(*) FROM market_prices WHERE view_kind='actual' AND price_date>'2027-02-28' UNION ALL SELECT 'fx',COUNT(*) FROM fx_rates WHERE view_kind='actual' AND as_of_date>'2027-02-28' UNION ALL SELECT 'trades',COUNT(*) FROM securities_transactions WHERE trade_status='executed' AND trade_date>'2027-02-28'")
 add(s,'For all portfolios in the future_limit business branch, compare current and March planned issuer assessment counts by status.','对“未来限额变更”业务分支的全部组合，按评估状态比较当前与三月计划的发行方评估数量。',"SELECT a.as_of_date,a.view_kind,a.assessment_status,COUNT(*) AS assessments FROM limit_assessments a JOIN mandate_limits l USING(limit_id) JOIN portfolios p USING(portfolio_id) WHERE p.branch='future_limit' AND l.measure='issuer_ratio' AND a.as_of_date IN ('2027-02-28','2027-03-31') GROUP BY a.as_of_date,a.view_kind,a.assessment_status ORDER BY a.as_of_date,a.assessment_status")
 add(s,'Check every assessment uses a known approved limit valid on its own date; report breaches of this rule by view.','检查每项评估是否采用当时已知、已批准且在评估日有效的限额，按视图报告规则违规数。',"SELECT a.view_kind,COUNT(*) AS assessments,SUM(CASE WHEN a.as_of_date<l.effective_from_date OR a.as_of_date>l.effective_to_date OR l.decision_date>a.known_date OR l.approval<>'approved' THEN 1 ELSE 0 END) AS invalid_limit_uses FROM limit_assessments a JOIN mandate_limits l USING(limit_id) GROUP BY a.view_kind ORDER BY a.view_kind")
 assert len(questions)==100 and all(n==10 for n in counts.values())
 known={r['id'] for r in json.loads((sample/'model-contract.json').read_text())['relations']}
 for q in questions:
  assert set(q['required_relations'])<=known,(q['id'],set(q['required_relations'])-known)
 jwrite(sample/'bkn-eval'/'questions.json',questions);jwrite(sample/'bkn-eval'/'expected-results.json',answers)
 jwrite(sample/'bkn-eval'/'scenarios.json',[dict(id=f'S{i+1:02}',title=t[1 if zh else 0],scenario_relations=PATHS[f'S{i+1:02}'],question_ids=[q['id'] for q in questions if q['scenario_id']==f'S{i+1:02}']) for i,t in enumerate(TITLES)])
 db.close()
